args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?later ?laterLabel ?lakutisBirth ?jeffBirth WHERE {
  OPTIONAL { dbr:Lakutis dbo:birthDate ?lakutisBD. }
  OPTIONAL { dbr:Lakutis dbp:birthDate ?lakutisBD2. }
  BIND(COALESCE(?lakutisBD, ?lakutisBD2) AS ?lakutisBirth)

  OPTIONAL { dbr:Jeff_Fabry dbo:birthDate ?jeffBD. }
  OPTIONAL { dbr:Jeff_Fabry dbp:birthDate ?jeffBD2. }
  BIND(COALESCE(?jeffBD, ?jeffBD2) AS ?jeffBirth)

  FILTER(BOUND(?lakutisBirth) && BOUND(?jeffBirth))

  BIND(IF(?lakutisBirth > ?jeffBirth, dbr:Lakutis, dbr:Jeff_Fabry) AS ?later)
  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(lang(?laterLabel) = 'en') }
}

